    39→pub(crate) const SIZES: [u64; 4] = {
    40→    let mut ret = [0u64; 4];
    41→    let mut size = 1;
    42→    while size < 64 {
    43→        let k = item_byte(Tag::SymbolSize(size));
    44→        ret[((k & 0b11000000) >> 6) as usize] |= 1u64 << (k & 0b00111111);
    45→        size += 1;
    46→    }
    47→    ret
    48→};
    49→pub(crate) const ARITIES: [u64; 4] = {
    50→    let mut ret = [0u64; 4];
    51→    let mut arity = 1;
    52→    while arity < 64 {
    53→        let k = item_byte(Tag::Arity(arity));
    54→        ret[((k & 0b11000000) >> 6) as usize] |= 1u64 << (k & 0b00111111);
    55→        arity += 1;
    56→    }
    57→    ret
    58→};
    59→pub(crate) const VARS: [u64; 4] = {
    60→    let mut ret = [0u64; 4];
    61→    let nv_byte = item_byte(Tag::NewVar);
    62→    ret[((nv_byte & 0b11000000) >> 6) as usize] |= 1u64 << (nv_byte & 0b00111111);
    63→    let mut size = 0;
    64→    while size < 64 {
    65→        let k = item_byte(Tag::VarRef(size));
    66→        ret[((k & 0b11000000) >> 6) as usize] |= 1u64 << (k & 0b00111111);
    67→        size += 1;
    68→    }
    69→    ret
    70→};
