    72→
    73→// future Adam: don't fall for the temptation of keeping references of data->pattern, you tried it twice already: it's not worth the complexity, it's incompatible due to the PZ de-Bruijn level non-well-foundedness, it doesn't occur in most queries, and the performance is not worth it
    74→// others: this code has haphephobia, contact Adam when you run into problems
    75→// optimization opportunities:
    76→// - use u16 x u16 compressed byte mask to reduce stack size, or to_next_sibling?
    77→// - decrease the size of ExprEnv; it's too rich for this function
    78→// - this function gets massive (many thousands of instructions) but can do with less checked functions
    79→// - ascends may be avoided by using RZ refs instead of re-ascending in some cases
    80→// - the adiabatic crate may be used to get rid of the recursion (though currently the recursion is significantly faster)
    81→// - `references` can be elided by not putting the virtual $ Expr's on the `stack` such that _k maps directly to the indices
    82→// - keeping a needle instead of a stack to avoid the `reverse` (would also create the opportunity to be even more lazy about instruction gen)
    83→// - use descend_to and re-evaluated the added sub-path to do much better on long paths
    84→fn coreferential_transition<Z : ZipperMoving + Zipper + ZipperAbsolutePath + ZipperIteration, F: FnMut(&mut Z) -> ()>(
    85→    loc: &mut Z, mut stack: &mut Vec<ExprEnv>, references: &mut Vec<u32>, f: &mut F) {
    86→    macro_rules! vs {
    87→        ($e:expr, $nv:expr) => {{
    88→            let m = loc.child_mask().and(&ByteMask(VARS));
    89→            let mut it = m.iter();
    90→
    91→            while let Some(b) = it.next() {
    92→                // technically requires us to replace references to this NewVar on the stack with e
    93→                // if !$nv && item_byte(Tag::NewVar) == b {
    94→                //     if $e.n == 0 {
    95→                //         references.push(u32::MAX);
    96→                //     }
    97→                // }
    98→                loc.descend_to_byte(b);
    99→                debug_assert!(loc.path_exists());
   100→                coreferential_transition(loc, stack, references, f);
   101→                if !loc.ascend_byte() { unreachable_unchecked() };
   102→            }
   103→        }};
   104→    }
   105→    unsafe {
   106→    trace!(target: "coref trans", "loc {}    len {}", serialize(loc.path()), loc.path().len());
   107→    // trace!(target: "coref trans", "loc {} ({:?})    len {}    ops {:?} ({:?})", serialize(loc.path()), loc.path(), loc.path().len(), loc.child_mask(), loc.child_mask().iter().map(byte_item).collect::<Vec<_>>());
   108→    trace!(target: "coref trans", "top {}", stack.last().map(|x| x.show()).unwrap_or_else(|| "empty".into()));
   109→    unsafe { transitions += 1 };
   110→    match stack.pop() {
   111→        None => { f(loc) }
